CREATE TABLE IF NOT EXISTS story_rooms(id TEXT PRIMARY KEY,topic TEXT NOT NULL,kind TEXT NOT NULL,draft TEXT NOT NULL DEFAULT '',revision INTEGER NOT NULL DEFAULT 0,last_submission TEXT,updated INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS story_members(token_hash TEXT PRIMARY KEY,room TEXT NOT NULL,name TEXT NOT NULL,seen INTEGER NOT NULL,typing_until INTEGER NOT NULL DEFAULT 0,last_submit INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS story_members_room ON story_members(room,seen);
CREATE TABLE IF NOT EXISTS story_lines(id TEXT PRIMARY KEY,room TEXT NOT NULL,member_hash TEXT NOT NULL,name TEXT NOT NULL,role TEXT NOT NULL,line TEXT NOT NULL,revision INTEGER NOT NULL,created INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS story_lines_room ON story_lines(room,revision);
CREATE TABLE IF NOT EXISTS story_limits(key TEXT PRIMARY KEY,n INTEGER NOT NULL);
